import { readdirSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { variables, folderColours } from './variables.mjs';
import { icons, iconUrl } from './icons.mjs';

const partialsDir = join(import.meta.dirname, 'css');

const header = `/*
 * Oxocarbon Grey for Obsidian
 * Generated by src/build.mjs from the oxocarbon-grey palette. Edit src/, not this file.
 * Layout ideas follow the Border theme by Akifyss (MIT). Icons are from Lucide (ISC).
 */
`;

const block = (selector, declarations) =>
  `${selector} {\n${Object.entries(declarations)
    .map(([name, value]) => `  ${name}: ${value};`)
    .join('\n')}\n}\n`;

// Obsidian puts an empty spacer element before the first folder, so the
// first folder is child 2.
const folderRules = () =>
  folderColours
    .map(
      (hex, i) =>
        `body:not(.oxg-plain-folders) .nav-folder:nth-child(${folderColours.length}n + ${i + 2}) {\n  --oxg-folder-colour: ${hex};\n}\n`,
    )
    .join('\n');

const partials = () =>
  readdirSync(partialsDir)
    .filter((name) => name.endsWith('.css'))
    .sort()
    .map((name) => readFileSync(join(partialsDir, name), 'utf8'));

export const render = () =>
  [
    header,
    block(
      'body',
      Object.fromEntries(Object.entries(icons).map(([name, body]) => [`--oxg-icon-${name}`, iconUrl(body)])),
    ),
    block('.theme-dark', variables),
    folderRules(),
    ...partials(),
  ].join('\n');
